package com.dankscripts.sgjdestiny_dhd.compat;

/** Baseline equivalent to the hardware generated by the Forge ship console. */
public final class DestinyHardwiredDHD {
    public static final int CONNECTION_RANGE = 32;

    private DestinyHardwiredDHD() {}

    public static long energyTarget(long nativeTarget, long rawTarget, long regularCrystalTarget) {
        long baseline = regularCrystalTarget > Long.MAX_VALUE / 3
                ? Long.MAX_VALUE : regularCrystalTarget * 3;
        return rawTarget < 0 ? nativeTarget : Math.max(nativeTarget, baseline);
    }

    public static long energyTransfer(long nativeTransfer, long rawTransfer, long regularCrystalTransfer) {
        return rawTransfer < 0 ? nativeTransfer : Math.max(nativeTransfer, regularCrystalTransfer);
    }

    public static double connectionRange(double nativeRange) {
        return Math.max(nativeRange, CONNECTION_RANGE);
    }

    public static boolean canDiscover(double distanceSqr, double range, boolean gateHasController) {
        return !gateHasController && distanceSqr <= range * range;
    }

    public static boolean canReleaseOneSidedOwner(boolean sameOwner, boolean receiverEmpty,
                                                   boolean inRange, boolean gateIdle) {
        return sameOwner && receiverEmpty && inRange && gateIdle;
    }
}
